import{_ as a,o as s,c as t,ag as l}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科技周刊 #408 配套阅读·要点纪要","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/weekly-408-readings.md","filePath":"topics/ai-system-architecture/weekly-408-readings.md"}'),e={name:"topics/ai-system-architecture/weekly-408-readings.md"};function r(n,i,o,h,u,d){return s(),t("div",null,[...i[0]||(i[0]=[l(`<h1 id="科技周刊-408-配套阅读·要点纪要" tabindex="-1">科技周刊 #408 配套阅读·要点纪要 <a class="header-anchor" href="#科技周刊-408-配套阅读·要点纪要" aria-label="Permalink to &quot;科技周刊 #408 配套阅读·要点纪要&quot;">​</a></h1><blockquote><p>来源：阮一峰科技爱好者周刊 #408 各链接正文·已抓取提炼 定位：周刊中&quot;值得深入了解&quot;的技术内容要点，与主打内容(LLM缓存)互补</p></blockquote><hr><h2 id="一、工程与架构" tabindex="-1">一、工程与架构 <a class="header-anchor" href="#一、工程与架构" aria-label="Permalink to &quot;一、工程与架构&quot;">​</a></h2><h3 id="_1-任务执行工具-use-task-runners" tabindex="-1">1. 任务执行工具（Use Task Runners） <a class="header-anchor" href="#_1-任务执行工具-use-task-runners" aria-label="Permalink to &quot;1. 任务执行工具（Use Task Runners）&quot;">​</a></h3><ul><li>原理解法：跨仓库统一&quot;常见命令&quot;，不记 clunky 命令行</li><li>核心痛点：每个仓库技术栈不同，install/build/lint/format/test/migrate 命令全靠记</li><li>方案：用 task runner（make/just/mise 等）把常用操作抽象成一致命令</li><li><strong>价值</strong>：一致性优于具体工具选择</li></ul><h3 id="_2-github-脚本上传附件-重点-有实操价值" tabindex="-1">2. GitHub 脚本上传附件（重点，有实操价值） <a class="header-anchor" href="#_2-github-脚本上传附件-重点-有实操价值" aria-label="Permalink to &quot;2. GitHub 脚本上传附件（重点，有实操价值）&quot;">​</a></h3><ul><li>长期痛点：GitHub 没有官方 API 上传图片到 Issue/PR/Comment</li><li>现在有一个 <strong>未经官方文档化</strong> 的端点：<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://uploads.github.com/user-attachments/assets?name=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$FILE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&amp;content_type=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$MIME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&amp;repository_id=$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api repos/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$REPO</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .id)&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Accept: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data-binary</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$FILE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div></li><li>用途：CI 自动贴 demo 截图/测试失败截图/视觉 diff</li><li>⚠️ 未文档化，可能不稳定（作者原文也说 &quot;for now&quot;）</li></ul><h3 id="_3-canvas-而非-html-构建-webapp" tabindex="-1">3. Canvas 而非 HTML 构建 WebApp <a class="header-anchor" href="#_3-canvas-而非-html-构建-webapp" aria-label="Permalink to &quot;3. Canvas 而非 HTML 构建 WebApp&quot;">​</a></h3><ul><li>背景：Google/Microsoft 等巨头的复杂应用倾向用 Canvas 呈现整个页面</li><li>Canvas 优点：完全控制渲染、跨设备性能一致、无需重排/回流</li><li>缺点：可访问性差、SEO 差、文本选择/屏幕阅读器失效</li><li><strong>结论</strong>：高实时交互/游戏/可视化场景用 Canvas；内容型网页仍用 HTML</li></ul><h3 id="_4-手机当服务器-termux" tabindex="-1">4. 手机当服务器（Termux） <a class="header-anchor" href="#_4-手机当服务器-termux" aria-label="Permalink to &quot;4. 手机当服务器（Termux）&quot;">​</a></h3><ul><li>作者把闲置安卓手机(CMF Phone 1)改成 Linux 服务器</li><li>配置：8 ARM 核/8G RAM/128G 闪存/WiFi6/5G/内置电池，SoC 性能过剩躺在抽屉</li><li>现跑：网页应用、远程浏览器(Surf)、个人财务追踪、屏幕共享、若干小应用</li><li><strong>价值</strong>：利用闲置硬件 + 已有投资，替代付费 VPS</li></ul><h3 id="_5-电梯算法" tabindex="-1">5. 电梯算法 <a class="header-anchor" href="#_5-电梯算法" aria-label="Permalink to &quot;5. 电梯算法&quot;">​</a></h3><ul><li>SCAN（1961，横扫到底再返回）vs LOOK（只到最远请求即反向）——多数人熟悉的</li><li>多电梯协调：中央调度把请求分给最近电梯；可进一步优化</li><li>质量度量：非&quot;平均等待&quot;，而是&quot;30秒/90秒内到达率&quot;</li><li>动画演示优化空间</li></ul><hr><h2 id="二、安全与隐私-本期最值得警惕" tabindex="-1">二、安全与隐私（本期最值得警惕） <a class="header-anchor" href="#二、安全与隐私-本期最值得警惕" aria-label="Permalink to &quot;二、安全与隐私（本期最值得警惕）&quot;">​</a></h2><h3 id="_6-蓝牙识别交通摄像头-signaltrace" tabindex="-1">6. 蓝牙识别交通摄像头（SignalTrace） <a class="header-anchor" href="#_6-蓝牙识别交通摄像头-signaltrace" aria-label="Permalink to &quot;6. 蓝牙识别交通摄像头（SignalTrace）&quot;">​</a></h3><ul><li>⚠️ <strong>重大隐私隐患</strong>：ALPR(自动车牌识别)加装传感器，除拍车牌还会捕获车内蓝牙设备 MAC</li><li>关联：手机/AirPods/手表 → 与车牌绑定 → 推断特定驾驶员/乘客</li><li>还能捕捉：钥匙卡/RFID 标签(宠物芯片)/车内 WiFi SSID</li><li><strong>关键</strong>：把&quot;跟踪车&quot;升级成&quot;跟踪特定的人&quot;。值得警惕的监控滥用</li></ul><hr><h2 id="三、ai-与工具" tabindex="-1">三、AI 与工具 <a class="header-anchor" href="#三、ai-与工具" aria-label="Permalink to &quot;三、AI 与工具&quot;">​</a></h2><h3 id="_7-cloudflare-os-企业-ai-门户" tabindex="-1">7. Cloudflare OS（企业 AI 门户） <a class="header-anchor" href="#_7-cloudflare-os-企业-ai-门户" aria-label="Permalink to &quot;7. Cloudflare OS（企业 AI 门户）&quot;">​</a></h3><ul><li>GitHub 开源：基于 Cloudflare Workers 的 Agent 工作区</li><li>功能：创建文档、构建应用、运行 agents，接入公司上下文与系统</li><li><strong>意义</strong>：企业级&quot;AI 内部门户&quot;，把 AI 代理/知识管理/自动化统一</li></ul><h3 id="_8-dbx-轻量数据库工具" tabindex="-1">8. DBX（轻量数据库工具） <a class="header-anchor" href="#_8-dbx-轻量数据库工具" aria-label="Permalink to &quot;8. DBX（轻量数据库工具）&quot;">​</a></h3><ul><li>20MB 跨平台，支持 70+ 数据库（MySQL/PostgreSQL/SQLite/Redis/MongoDB/DuckDB/达梦）</li><li>内建 AI + MCP Server + CLI/桌面/Docker</li><li><strong>价值</strong>：轻量 + 接入 AI/MCP</li></ul><h3 id="_9-docker-沙箱" tabindex="-1">9. Docker 沙箱 <a class="header-anchor" href="#_9-docker-沙箱" aria-label="Permalink to &quot;9. Docker 沙箱&quot;">​</a></h3><ul><li>Docker 官方为&quot;编码 Agent&quot;提供的隔离环境</li><li>用途：AI Agent 在容器内运行，与主机隔离</li></ul><h3 id="_10-声波灭火-infrasound" tabindex="-1">10. 声波灭火（Infrasound） <a class="header-anchor" href="#_10-声波灭火-infrasound" aria-label="Permalink to &quot;10. 声波灭火（Infrasound）&quot;">​</a></h3><ul><li>原理：强低频声波(约30Hz)把氧分子振离燃料，阻碍燃烧</li><li>演示：AI 传感器触发 → 壁音箱发射次声波 → 几秒内扑灭厨房小火</li><li><strong>局限</strong>：喇叭体积大/需离火源近/声波快速衰减 → 仅零星火势，难替换喷淋</li><li>价值：应对&quot;无人值守燃气灶起火&quot;这类场景前景可观，但替代喷淋存疑（专家也不看好）</li></ul><hr><h2 id="四、金句" tabindex="-1">四、金句 <a class="header-anchor" href="#四、金句" aria-label="Permalink to &quot;四、金句&quot;">​</a></h2><blockquote><ol><li>&quot;AI 省下的时间，不是休假的，而是开发更多产品。&quot; — Meta CTO</li><li>&quot;有很多理由本地运行大模型，但省钱不在其中。&quot; — OpenCode 创始人</li><li>&quot;本地跑 DeepSeek 需 24 年才收回成本。&quot;（量化：本地化省不了钱）</li></ol></blockquote><hr><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/zhishiku-reading/topics/ai-system-architecture/llm-cache-pricing.html">LLM 缓存定价</a>（#408 主打）</li><li><a href="/zhishiku-reading/topics/ai-system-architecture/">AI 系统架构索引</a></li></ul>`,34)])])}const c=a(e,[["render",r]]);export{p as __pageData,c as default};
